import{_ as l,C as c,o as t,c as u,a2 as n,b as i,w as e,a as s,E as r,a3 as d}from"./chunks/framework.CgxQ0r6v.js";const A=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 3","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_3.md","filePath":"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_3.md"}'),p={name:"materias/Edumatica/documentacion/IV-XII/Lectura_Catedra_Evaluacion_3.md"};function g(m,a,h,b,C,v){const o=c("Mermaid");return t(),u("div",null,[a[2]||(a[2]=n('<h1 id="manual-de-estudio-profundo-evaluacion-3" tabindex="-1">Manual de Estudio Profundo: Evaluación 3 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-3" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 3&quot;">​</a></h1><h2 id="materia-edumatica" tabindex="-1">Materia: EduMática <a class="header-anchor" href="#materia-edumatica" aria-label="Permalink to &quot;Materia: EduMática&quot;">​</a></h2><h3 id="eje-tematico-diseno-curricular-—-contenido-sinoptico-y-analitico" tabindex="-1">Eje Temático: Diseño Curricular — Contenido Sinóptico y Analítico <a class="header-anchor" href="#eje-tematico-diseno-curricular-—-contenido-sinoptico-y-analitico" aria-label="Permalink to &quot;Eje Temático: Diseño Curricular — Contenido Sinóptico y Analítico&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-ingenieria-detras-de-una-materia" tabindex="-1">🧭 Introducción: La Ingeniería Detrás de una Materia <a class="header-anchor" href="#🧭-introduccion-la-ingenieria-detras-de-una-materia" aria-label="Permalink to &quot;🧭 Introducción: La Ingeniería Detrás de una Materia&quot;">​</a></h2><p>Cuando te sientas en un salón de clases, ves al profesor dar su tema, asignar tareas y evaluar. Todo parece fluir de manera natural. Pero detrás de cada clase hay una <strong>arquitectura invisible</strong>: alguien tuvo que decidir qué temas se enseñan, en qué orden, con qué profundidad, qué recursos se usan y cómo se evalúa. Ese &quot;alguien&quot; diseñó una <strong>Unidad Curricular</strong>.</p><p>Diseñar un programa de asignatura no es simplemente listar temas. Es un ejercicio de <strong>ingeniería educativa</strong> que requiere comprender la estructura institucional, las necesidades del perfil profesional, los niveles cognitivos que se desean alcanzar y las estrategias más efectivas para lograrlo. Este manual te enseñará a analizar y construir esa arquitectura desde cero.</p><hr><h2 id="🏛️-capitulo-i-la-unidad-curricular" tabindex="-1">🏛️ CAPÍTULO I: La Unidad Curricular <a class="header-anchor" href="#🏛️-capitulo-i-la-unidad-curricular" aria-label="Permalink to &quot;🏛️ CAPÍTULO I: La Unidad Curricular&quot;">​</a></h2><h3 id="_1-1-definicion" tabindex="-1">1.1 Definición <a class="header-anchor" href="#_1-1-definicion" aria-label="Permalink to &quot;1.1 Definición&quot;">​</a></h3><p>Una <strong>Unidad Curricular</strong> es el componente básico de un plan de estudios. Representa una materia, asignatura o módulo con identidad propia, que contribuye al logro del perfil profesional del egresado. Cada unidad curricular tiene:</p><ul><li>Un <strong>nombre</strong> identificador (ej. &quot;Algorítmica y Programación&quot;).</li><li>Un <strong>código</strong> (ej. &quot;AP123&quot;).</li><li>Una cantidad de <strong>unidades crédito</strong> que reflejan la carga académica.</li><li>Una <strong>duración</strong> definida (1 o más trimestres).</li><li>Un conjunto de <strong>saberes</strong> (contenidos) organizados en unidades temáticas.</li><li><strong>Estrategias</strong> de enseñanza y <strong>criterios de evaluación</strong>.</li></ul><h3 id="_1-2-estructura-jerarquica-del-curriculo" tabindex="-1">1.2 Estructura Jerárquica del Currículo <a class="header-anchor" href="#_1-2-estructura-jerarquica-del-curriculo" aria-label="Permalink to &quot;1.2 Estructura Jerárquica del Currículo&quot;">​</a></h3><p>Para entender dónde se ubica la unidad curricular dentro del sistema educativo, observemos la jerarquía completa:</p>',14)),(t(),i(d,null,{default:e(()=>[r(o,{id:"mermaid-67",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20PNF%5B%22%F0%9F%8F%9B%EF%B8%8F%20PNF%20-%20Programa%20Nacional%20de%20Formaci%C3%B3n%22%5D%20--%3E%20T%5B%22%F0%9F%93%85%20Trayecto%22%5D%0A%20%20%20%20T%20--%3E%20TR%5B%22%F0%9F%93%86%20Trimestre%22%5D%0A%20%20%20%20TR%20--%3E%20UC%5B%22%F0%9F%93%9A%20Unidad%20Curricular%22%5D%0A%20%20%20%20UC%20--%3E%20UT%5B%22%F0%9F%93%96%20Unidad%20Tem%C3%A1tica%22%5D%0A%20%20%20%20UT%20--%3E%20C%5B%22%F0%9F%93%9D%20Contenido%20Espec%C3%ADfico%22%5D%0A%0A%20%20%20%20style%20PNF%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A%20%20%20%20style%20T%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20TR%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20UC%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20UT%20fill%3A%231a1a2e%2Cstroke%3A%23ff9f43%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20C%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n(`<table tabindex="0"><thead><tr><th>Nivel</th><th>Descripción</th><th>Ejemplo (PNFI)</th></tr></thead><tbody><tr><td><strong>PNF</strong></td><td>El programa completo de la carrera.</td><td>Programa Nacional de Formación en Informática (PNFI).</td></tr><tr><td><strong>Trayecto</strong></td><td>Gran bloque temporal (generalmente 1 año).</td><td>Trayecto II (segundo año).</td></tr><tr><td><strong>Trimestre</strong></td><td>Subdivisión del trayecto (3 meses).</td><td>Trimestre II-IV (cuarto trimestre del Trayecto II).</td></tr><tr><td><strong>Unidad Curricular</strong></td><td>La materia en sí.</td><td>&quot;Redes&quot;, &quot;Programación II&quot;, &quot;EduMática&quot;.</td></tr><tr><td><strong>Unidad Temática</strong></td><td>Gran tema dentro de la materia.</td><td>&quot;Unidad 3: Componentes de una red LAN&quot;.</td></tr><tr><td><strong>Contenido Específico</strong></td><td>Tema puntual dentro de la unidad temática.</td><td>&quot;Diferencia entre un Hub y un Switch&quot;.</td></tr></tbody></table><h3 id="_1-3-el-modulo" tabindex="-1">1.3 El Módulo <a class="header-anchor" href="#_1-3-el-modulo" aria-label="Permalink to &quot;1.3 El Módulo&quot;">​</a></h3><p>Un <strong>módulo</strong> es una variante de organización curricular que agrupa contenidos de forma <strong>autocontenida e interdisciplinaria</strong>. A diferencia de la unidad curricular tradicional (que separa saberes por disciplina), un módulo puede integrar conocimientos de varias áreas alrededor de un <strong>problema o competencia central</strong>.</p><table tabindex="0"><thead><tr><th>Característica</th><th>Unidad Curricular Tradicional</th><th>Módulo</th></tr></thead><tbody><tr><td><strong>Organización</strong></td><td>Por disciplina (Redes, Programación, etc.)</td><td>Por problema o competencia (&quot;Desarrollar un sistema web seguro&quot;).</td></tr><tr><td><strong>Enfoque</strong></td><td>Teórico-disciplinar</td><td>Práctico-integrador</td></tr><tr><td><strong>Evaluación</strong></td><td>Por contenido aprendido</td><td>Por competencia demostrada</td></tr><tr><td><strong>Ejemplo</strong></td><td>&quot;Programación II: Unidad 5 - Express.js&quot;</td><td>&quot;Proyecto: Construir un sistema CRUD con autenticación&quot;</td></tr></tbody></table><hr><h2 id="🧩-capitulo-ii-contenido-sinoptico-vs-contenido-analitico" tabindex="-1">🧩 CAPÍTULO II: Contenido Sinóptico vs. Contenido Analítico <a class="header-anchor" href="#🧩-capitulo-ii-contenido-sinoptico-vs-contenido-analitico" aria-label="Permalink to &quot;🧩 CAPÍTULO II: Contenido Sinóptico vs. Contenido Analítico&quot;">​</a></h2><p>Cuando se diseña una unidad curricular, su contenido se documenta en dos niveles de detalle:</p><h3 id="_2-1-contenido-sinoptico-vision-general" tabindex="-1">2.1 Contenido Sinóptico (Visión General) <a class="header-anchor" href="#_2-1-contenido-sinoptico-vision-general" aria-label="Permalink to &quot;2.1 Contenido Sinóptico (Visión General)&quot;">​</a></h3><p>Es el <strong>resumen ejecutivo</strong> del programa. Presenta los grandes bloques temáticos (unidades) con una descripción breve de cada uno. Es lo que normalmente se muestra en el pensum oficial de la carrera o en la presentación pública de la materia.</p><p><strong>Características:</strong></p><ul><li>Breve y conciso (generalmente 1-2 páginas).</li><li>Lista las unidades temáticas con sus títulos.</li><li>Incluye los objetivos generales de la materia.</li><li>No detalla contenidos específicos ni actividades.</li></ul><p><strong>Ejemplo de Contenido Sinóptico:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNIDAD CURRICULAR: Redes (RCT226)</span></span>
<span class="line"><span>TRAYECTO: II | CRÉDITOS: 6 | DURACIÓN: 2 Trimestres</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unidad 1: Fundamentos básicos de Redes</span></span>
<span class="line"><span>Unidad 2: Comunicación</span></span>
<span class="line"><span>Unidad 3: Componentes de una red LAN</span></span>
<span class="line"><span>Unidad 4: Redes de Telecomunicaciones y de Datos</span></span>
<span class="line"><span>Unidad 5: Protocolos de Redes</span></span>
<span class="line"><span>Unidad 6: Ancho de Banda y Tecnologías</span></span>
<span class="line"><span>...</span></span></code></pre></div><h3 id="_2-2-contenido-analitico-desglose-detallado" tabindex="-1">2.2 Contenido Analítico (Desglose Detallado) <a class="header-anchor" href="#_2-2-contenido-analitico-desglose-detallado" aria-label="Permalink to &quot;2.2 Contenido Analítico (Desglose Detallado)&quot;">​</a></h3><p>Es el <strong>plano arquitectónico completo</strong> del programa. Descompone cada unidad temática en sus contenidos específicos, objetivos particulares, estrategias de enseñanza, recursos y criterios de evaluación.</p><p><strong>Características:</strong></p><ul><li>Extenso y detallado (puede ocupar varias páginas).</li><li>Desglosa cada unidad en sub-temas con viñetas.</li><li>Especifica los objetivos de aprendizaje por unidad (usando verbos de Bloom).</li><li>Incluye las estrategias de evaluación y los recursos necesarios.</li><li>Sirve como guía operativa para el docente.</li></ul><p><strong>Ejemplo de Contenido Analítico (fragmento):</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNIDAD 2: Comunicación</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Objetivos específicos:</span></span>
<span class="line"><span>- Identificar los tipos de medios de conexión de redes.</span></span>
<span class="line"><span>- Diferenciar entre cable STP y UTP según sus características.</span></span>
<span class="line"><span>- Implementar cableado con RJ45 aplicando los estándares 568A y 568B.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Contenidos:</span></span>
<span class="line"><span>- Líneas de Comunicación: Definición, clasificación.</span></span>
<span class="line"><span>  - Conmutadas, dedicadas, punto a punto, multipunto, digitales.</span></span>
<span class="line"><span>- Medios de conexión:</span></span>
<span class="line"><span>  - Cobre (par trenzado), Fibra Óptica, Inalámbrico.</span></span>
<span class="line"><span>- Tipos de cable: STP, UTP (Categorías 5e, 6, 6a).</span></span>
<span class="line"><span>- Conectores: Jack, RJ45.</span></span>
<span class="line"><span>- Implementación del cableado:</span></span>
<span class="line"><span>  - Cable directo (568B-568B).</span></span>
<span class="line"><span>  - Cable cruzado (568A-568B).</span></span>
<span class="line"><span>  - Estándar EIA/TIA 568A vs 568B.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Estrategias: Clase magistral, laboratorio práctico de ponchado.</span></span>
<span class="line"><span>Recursos: Cables UTP Cat6, Crimpeadora, Tester, RJ45.</span></span>
<span class="line"><span>Evaluación: Laboratorio práctico (25%).</span></span></code></pre></div><h3 id="_2-3-tabla-comparativa" tabindex="-1">2.3 Tabla Comparativa <a class="header-anchor" href="#_2-3-tabla-comparativa" aria-label="Permalink to &quot;2.3 Tabla Comparativa&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspecto</th><th>Sinóptico</th><th>Analítico</th></tr></thead><tbody><tr><td><strong>Nivel de detalle</strong></td><td>General, resumen</td><td>Específico, desglosado</td></tr><tr><td><strong>Extensión</strong></td><td>1-2 páginas</td><td>Varias páginas</td></tr><tr><td><strong>Audiencia</strong></td><td>Autoridades, pensum público, estudiantes</td><td>Docente, coordinación académica</td></tr><tr><td><strong>Contenido</strong></td><td>Títulos de unidades y objetivos generales</td><td>Sub-temas, objetivos específicos, estrategias, recursos, evaluación</td></tr><tr><td><strong>Analogía</strong></td><td>El índice de un libro</td><td>El libro completo con notas del autor</td></tr><tr><td><strong>Pregunta que responde</strong></td><td>&quot;¿Qué se va a enseñar?&quot;</td><td>&quot;¿Cómo, con qué y cuándo se va a enseñar?&quot;</td></tr></tbody></table><hr><h2 id="🏗️-capitulo-iii-tecnicas-para-disenar-un-programa-de-asignatura" tabindex="-1">🏗️ CAPÍTULO III: Técnicas para Diseñar un Programa de Asignatura <a class="header-anchor" href="#🏗️-capitulo-iii-tecnicas-para-disenar-un-programa-de-asignatura" aria-label="Permalink to &quot;🏗️ CAPÍTULO III: Técnicas para Diseñar un Programa de Asignatura&quot;">​</a></h2><h3 id="_3-1-seleccion-de-contenidos" tabindex="-1">3.1 Selección de Contenidos <a class="header-anchor" href="#_3-1-seleccion-de-contenidos" aria-label="Permalink to &quot;3.1 Selección de Contenidos&quot;">​</a></h3><p>No todo lo que existe sobre un tema puede (ni debe) enseñarse. La selección de contenidos debe basarse en:</p><table tabindex="0"><thead><tr><th>Criterio</th><th>Pregunta Guía</th></tr></thead><tbody><tr><td><strong>Pertinencia</strong></td><td>¿Este contenido es relevante para el perfil profesional del egresado?</td></tr><tr><td><strong>Actualidad</strong></td><td>¿Este contenido refleja el estado actual de la disciplina o está obsoleto?</td></tr><tr><td><strong>Viabilidad</strong></td><td>¿Se puede enseñar este contenido con los recursos y el tiempo disponibles?</td></tr><tr><td><strong>Secuencia lógica</strong></td><td>¿Este contenido tiene prerrequisitos? ¿Viene antes o después de otro tema?</td></tr><tr><td><strong>Nivel cognitivo</strong></td><td>¿A qué nivel de Bloom apunta este contenido? ¿Es apropiado para el trayecto?</td></tr></tbody></table><h3 id="_3-2-seleccion-de-estrategias-de-ensenanza" tabindex="-1">3.2 Selección de Estrategias de Enseñanza <a class="header-anchor" href="#_3-2-seleccion-de-estrategias-de-ensenanza" aria-label="Permalink to &quot;3.2 Selección de Estrategias de Enseñanza&quot;">​</a></h3><p>Las estrategias deben alinearse con el tipo de contenido y el nivel cognitivo deseado:</p><table tabindex="0"><thead><tr><th>Tipo de Contenido</th><th>Estrategia Recomendada</th><th>Justificación</th></tr></thead><tbody><tr><td><strong>Conceptual</strong> (definiciones, teorías)</td><td>Clase magistral, lectura dirigida, mapas conceptuales</td><td>Facilita la comprensión y organización de información abstracta.</td></tr><tr><td><strong>Procedimental</strong> (pasos, técnicas)</td><td>Laboratorio, taller, demostración práctica</td><td>Permite al alumno ejecutar y practicar el procedimiento directamente.</td></tr><tr><td><strong>Actitudinal</strong> (valores, disposiciones)</td><td>Debate, estudio de casos, role-playing</td><td>Genera reflexión, empatía y posicionamiento personal.</td></tr><tr><td><strong>Integrador</strong> (proyectos complejos)</td><td>ABP (Aprendizaje Basado en Proyectos), simulaciones</td><td>Requiere que el alumno combine conocimientos de múltiples áreas.</td></tr></tbody></table><h3 id="_3-3-seleccion-de-recursos" tabindex="-1">3.3 Selección de Recursos <a class="header-anchor" href="#_3-3-seleccion-de-recursos" aria-label="Permalink to &quot;3.3 Selección de Recursos&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recurso</th><th>Cuándo Usarlo</th></tr></thead><tbody><tr><td><strong>Pizarra / Marcadores</strong></td><td>Explicaciones espontáneas, diagramas rápidos, resolución de dudas.</td></tr><tr><td><strong>Presentaciones Digitales</strong></td><td>Contenido estructurado con apoyo visual (imágenes, diagramas).</td></tr><tr><td><strong>Laboratorios de Computación</strong></td><td>Práctica directa con software, programación, configuración de redes.</td></tr><tr><td><strong>Material Impreso</strong></td><td>Guías de estudio, lecturas complementarias, hojas de ejercicios.</td></tr><tr><td><strong>Plataformas LMS</strong></td><td>Contenido asincrónico, foros, entregas de tareas (Moodle, Classroom).</td></tr><tr><td><strong>Software Educativo</strong></td><td>Simuladores, tutoriales interactivos, evaluaciones automatizadas.</td></tr></tbody></table><h3 id="_3-4-diseno-de-la-evaluacion" tabindex="-1">3.4 Diseño de la Evaluación <a class="header-anchor" href="#_3-4-diseno-de-la-evaluacion" aria-label="Permalink to &quot;3.4 Diseño de la Evaluación&quot;">​</a></h3><p>La evaluación debe ser <strong>coherente</strong> con los objetivos de aprendizaje. Si el objetivo dice &quot;el alumno será capaz de <strong>implementar</strong> un cable de red&quot;, la evaluación no puede ser un examen de selección múltiple; debe ser un laboratorio práctico.</p><table tabindex="0"><thead><tr><th>Nivel de Bloom</th><th>Instrumento de Evaluación Sugerido</th></tr></thead><tbody><tr><td><strong>Recordar / Comprender</strong></td><td>Examen escrito (selección múltiple, verdadero/falso, completar).</td></tr><tr><td><strong>Aplicar</strong></td><td>Laboratorio práctico, ejercicios de resolución de problemas.</td></tr><tr><td><strong>Analizar</strong></td><td>Estudio de casos, análisis comparativo escrito.</td></tr><tr><td><strong>Evaluar</strong></td><td>Ensayo crítico, debate evaluado con rúbrica.</td></tr><tr><td><strong>Crear</strong></td><td>Proyecto final, desarrollo de software, diseño de una solución.</td></tr></tbody></table>`,34)),(t(),i(d,null,{default:e(()=>[r(o,{id:"mermaid-642",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20OBJ%5B%22%F0%9F%8E%AF%20Objetivo%20de%20Aprendizaje%22%5D%20--%3E%20EST%5B%22%F0%9F%93%8B%20Estrategia%20de%20Ense%C3%B1anza%22%5D%0A%20%20%20%20EST%20--%3E%20REC%5B%22%F0%9F%9B%A0%EF%B8%8F%20Recursos%22%5D%0A%20%20%20%20REC%20--%3E%20EVA%5B%22%E2%9C%85%20Evaluaci%C3%B3n%22%5D%0A%20%20%20%20EVA%20-.-%3E%7C%22Debe%20ser%20coherente%20con%22%7C%20OBJ%0A%0A%20%20%20%20style%20OBJ%20fill%3A%230066ff%2Cstroke%3A%230044cc%2Ccolor%3A%23fff%0A%20%20%20%20style%20EST%20fill%3A%231a1a2e%2Cstroke%3A%2300d2ff%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20REC%20fill%3A%231a1a2e%2Cstroke%3A%2300ff88%2Ccolor%3A%23e0e0e0%0A%20%20%20%20style%20EVA%20fill%3A%231a1a2e%2Cstroke%3A%23ff6b6b%2Ccolor%3A%23e0e0e0%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n(`<div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Principio de Coherencia Curricular:</strong> Objetivos, estrategias, recursos y evaluación deben estar alineados. Si cambias uno, los demás deben ajustarse. Un programa donde los objetivos apuntan a &quot;crear&quot; pero la evaluación solo mide &quot;recordar&quot; es incoherente y deficiente.</p></div><hr><h2 id="🧪-capitulo-iv-actividades-de-consolidacion" tabindex="-1">🧪 CAPÍTULO IV: Actividades de Consolidación <a class="header-anchor" href="#🧪-capitulo-iv-actividades-de-consolidacion" aria-label="Permalink to &quot;🧪 CAPÍTULO IV: Actividades de Consolidación&quot;">​</a></h2><h3 id="actividad-1-analisis-de-una-unidad-curricular-real" tabindex="-1">Actividad 1: Análisis de una Unidad Curricular Real <a class="header-anchor" href="#actividad-1-analisis-de-una-unidad-curricular-real" aria-label="Permalink to &quot;Actividad 1: Análisis de una Unidad Curricular Real&quot;">​</a></h3><p>Selecciona una materia del PNFI que estés cursando actualmente. Obtén su contenido programático oficial y analiza:</p><ul><li>¿Cuántas unidades temáticas tiene?</li><li>¿Los objetivos están redactados con verbos de Bloom? ¿A qué niveles apuntan?</li><li>¿Las estrategias de evaluación son coherentes con los objetivos?</li><li>¿Qué mejorarías?</li></ul><h3 id="actividad-2-del-sinoptico-al-analitico" tabindex="-1">Actividad 2: Del Sinóptico al Analítico <a class="header-anchor" href="#actividad-2-del-sinoptico-al-analitico" aria-label="Permalink to &quot;Actividad 2: Del Sinóptico al Analítico&quot;">​</a></h3><p>A partir del siguiente contenido sinóptico ficticio, desarrolla el contenido analítico completo para <strong>una</strong> de las unidades:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UNIDAD CURRICULAR: Seguridad Informática (SI301)</span></span>
<span class="line"><span>TRAYECTO: III | CRÉDITOS: 4</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Unidad 1: Fundamentos de la Seguridad de la Información</span></span>
<span class="line"><span>Unidad 2: Criptografía y Protocolos Seguros</span></span>
<span class="line"><span>Unidad 3: Administración de Firewalls y Proxys</span></span>
<span class="line"><span>Unidad 4: Auditoría y Respuesta ante Incidentes</span></span></code></pre></div><p>Tu contenido analítico debe incluir: objetivos específicos (con verbos de Bloom), contenidos desglosados, estrategias de enseñanza, recursos y forma de evaluación.</p><h3 id="actividad-3-coherencia-curricular" tabindex="-1">Actividad 3: Coherencia Curricular <a class="header-anchor" href="#actividad-3-coherencia-curricular" aria-label="Permalink to &quot;Actividad 3: Coherencia Curricular&quot;">​</a></h3><p>Identifica <strong>3 casos de incoherencia</strong> en los siguientes fragmentos de programa y explica por qué son problemáticos:</p><ol><li><strong>Objetivo:</strong> &quot;El alumno será capaz de <em>diseñar</em> un esquema de base de datos.&quot; <strong>Evaluación:</strong> Examen de selección múltiple.</li><li><strong>Objetivo:</strong> &quot;El alumno será capaz de <em>configurar</em> un servidor web Apache.&quot; <strong>Estrategia:</strong> Clase magistral (solo teoría). <strong>Recursos:</strong> Pizarra y marcadores.</li><li><strong>Objetivo:</strong> &quot;El alumno será capaz de <em>listar</em> los protocolos del modelo OSI.&quot; <strong>Evaluación:</strong> Proyecto integrador de investigación de 20 páginas.</li></ol><hr><h2 id="📘-anexo-diccionario-tecnico-formal" tabindex="-1">📘 ANEXO: Diccionario Técnico Formal <a class="header-anchor" href="#📘-anexo-diccionario-tecnico-formal" aria-label="Permalink to &quot;📘 ANEXO: Diccionario Técnico Formal&quot;">​</a></h2><ul><li><strong>Unidad Curricular:</strong> Componente estructural del plan de estudios que integra un conjunto organizado de saberes, competencias y experiencias de aprendizaje bajo una identidad temática propia, con créditos académicos asignados.</li><li><strong>Contenido Sinóptico:</strong> Documento curricular que presenta una visión general y resumida de los temas principales de una unidad curricular, sin detallar sub-temas ni estrategias específicas.</li><li><strong>Contenido Analítico:</strong> Documento curricular que desglosa exhaustivamente cada unidad temática en contenidos específicos, objetivos particulares, estrategias de enseñanza, recursos y criterios de evaluación.</li><li><strong>Módulo Curricular:</strong> Unidad de organización del currículo que integra contenidos de múltiples disciplinas alrededor de un problema, competencia o situación profesional concreta.</li><li><strong>Perfil del Egresado:</strong> Conjunto de competencias, conocimientos, habilidades y actitudes que el graduado debe poseer al finalizar su formación profesional.</li><li><strong>Coherencia Curricular:</strong> Principio de diseño que exige la alineación lógica entre objetivos de aprendizaje, estrategias de enseñanza, recursos didácticos e instrumentos de evaluación.</li><li><strong>Estrategia de Enseñanza:</strong> Conjunto planificado de acciones, técnicas y procedimientos que el docente emplea para facilitar el proceso de aprendizaje en función de los objetivos propuestos.</li><li><strong>PNF (Programa Nacional de Formación):</strong> Marco curricular oficial del sistema de educación universitaria venezolano que estructura las carreras por trayectos, trimestres y unidades curriculares.</li><li><strong>Pertinencia Curricular:</strong> Grado en que los contenidos y actividades de un programa educativo responden a las necesidades reales del contexto social, laboral y profesional del egresado.</li></ul>`,16))])}const q=l(p,[["render",g]]);export{A as __pageData,q as default};
